// Returns gh44 colors when a gh44 theme is shown, else null so the caller keeps its own.
export function gh44Syntax(theme) {
  const background = String(theme.background).slice(0, 7).toLowerCase()
  const match = Object.values(GH44).find((v) => v.background.toLowerCase() === background)
  return match ? match.syntax : null
}
